#!/usr/bin/env python3
"""Regenerate docs/TEST_CATALOG.md from the skill's test_cases.json (CI checks it is in sync)."""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]
SRC = ROOT / ".claude" / "skills" / "merch-vendor-review" / "references" / "test_cases.json"


def render(data):
    tests = data["tests"]
    count = {n: sum(t["need"] == n for t in tests) for n in ("Must-have", "Important", "Nice-to-have")}
    lines = [f"# Check list (v{data['version']})", "",
             "Generated by `tools/gen_test_catalog.py` from `test_cases.json`. Do not edit by hand.", "",
             f"{len(tests)} checks: " + ", ".join(f"{v} {k}" for k, v in count.items()) + ".",
             "Only Must-have checks decide whether we can integrate. **risk** = a No/Open needs a change on our side.",
             "", "## Must-haves", ""]
    for i, g in enumerate(data["must_haves"], 1):
        extra = f"; any one of {', '.join(g['any'])}" if g.get("any") else ""
        lines.append(f"{i}. {g['item']} ({', '.join(g.get('all', []))}{extra})")
    for section in dict.fromkeys(t["section"] for t in tests):
        lines += ["", f"## {section}", "", "| ID | Need | Checked by | Check | What counts as yes | Tech note |",
                  "|---|---|---|---|---|---|"]
        for t in (t for t in tests if t["section"] == section):
            flag = " **risk**" if t.get("risk") else ""
            verify = t["verify"].replace("Doc", "Docs").replace("Live", "Sandbox")
            cells = [t["id"] + flag, t["need"], verify, t["test"], t["pass"], t["platform"]]
            lines.append("| " + " | ".join(c.replace("|", "\\|") for c in cells) + " |")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    out = ROOT / "docs" / "TEST_CATALOG.md"
    out.write_text(render(json.loads(SRC.read_text())))
    print(f"Wrote {out}")
